#nullable enable // autogenerated

using MVZ2.Sprites;
using UnityEditor;
using UnityEngine;

namespace MVZ2.Managers
{
    public partial class ResourceManager : MonoBehaviour
    {
        #region 生成Texture2D
        public Texture2D GenerateTexture2D(int width, int height, string name = "texture2D")
        {
            Texture2D texture = new Texture2D(width, height);
            texture.name = name;
            texture.hideFlags = HideFlags.HideAndDontSave;
            texture.alphaIsTransparency = true;
            RegisterGeneratedTexture2D(texture);
            return texture;
        }
        public Texture2D GenerateTextureFromBytes(byte[] bytes, string name = "texture2D")
        {
            Texture2D texture = GenerateTexture2D(2, 2, name);
            texture.LoadImage(bytes);
            texture.FixTransparency();
            return texture;
        }
        public void RemoveGeneratedTexture(Texture2D texture2D)
        {
            UnregisterGeneratedTexture2D(texture2D);
            Destroy(texture2D);
        }
        private void RegisterGeneratedTexture2D(Texture2D texture2D)
        {
            if (generatedResourceManifest)
            {
                generatedResourceManifest.AddTexture2D(texture2D);
            }
        }
        private void UnregisterGeneratedTexture2D(Texture2D texture2D)
        {
            if (generatedResourceManifest)
            {
                generatedResourceManifest.RemoveTexture2D(texture2D);
            }
        }
        #endregion

        #region 生成Sprite
        public Sprite CreateSprite(Texture2D texture, Rect rect, Vector2 pivot, string name, SpriteMeshType meshType = SpriteMeshType.Tight, string category = "default")
        {
            return CreateSprite(texture, rect, pivot, name, Vector4.zero, meshType, category);
        }
        public Sprite CreateSprite(Texture2D texture, Rect rect, Vector2 pivot, string name, Vector4 border, SpriteMeshType meshType = SpriteMeshType.Tight, string category = "default")
        {
            var sprite = Sprite.Create(texture, rect, pivot, 100f, 0, meshType, border);
            sprite.name = name;
            sprite.hideFlags = HideFlags.HideAndDontSave;
            RegisterGeneratedSprite(sprite, category);
            return sprite;
        }
        public void RemoveGeneratedSprite(Sprite sprite, string name, string category)
        {
            UnregisterGeneratedSprite(name, category);
            Destroy(sprite);
        }
        private void RegisterGeneratedSprite(Sprite sprite, string category)
        {
            if (generatedResourceManifest)
            {
                var width = Mathf.Min(backgroundTex.width, sprite.rect.width);
                var height = Mathf.Min(backgroundTex.height, sprite.rect.height);
                var rect = new Rect(0, 0, width, height);
                var background = Sprite.Create(backgroundTex, rect, sprite.pivot);
                background.name = sprite.name;
                generatedResourceManifest.AddSprite(category, sprite, background);
            }
        }
        private void UnregisterGeneratedSprite(string name, string category)
        {
            if (generatedResourceManifest)
            {
                generatedResourceManifest.RemoveSprite(category, name);
            }
        }
        #endregion

        #region 清除生成的贴图
        private void ClearGeneratedSpriteManifest()
        {
            if (generatedResourceManifest)
            {
                generatedResourceManifest.Clear();
            }
        }
        #endregion

        #region 生成贴图背景
        private Texture2D GenerateSpriteBackgroundTexture(int width, int height)
        {
            var tex = GenerateTexture2D(width, height);
            tex.name = "sprite_background_texture";
            var gray = new Color32(127, 127, 127, 255);
            var darkGray = new Color32(63, 63, 63, 255);
            var colorBuffer = spriteColorBuffer;
            for (int x = 0; x < width; x += COLOR_BUFFER_WIDTH)
            {
                var w = Mathf.Min(COLOR_BUFFER_WIDTH, width - x);
                for (int y = 0; y < height; y += COLOR_BUFFER_HEIGHT)
                {
                    var h = Mathf.Min(COLOR_BUFFER_HEIGHT, height - y);
                    for (int ix = 0; ix < w; ix++)
                    {
                        for (int iy = 0; iy < h; iy++)
                        {
                            var dstX = x + ix;
                            var dstY = x + iy;
                            var dstIndex = iy * w + ix;
                            colorBuffer[dstIndex] = ((dstX / 16) + (dstY / 16)) % 2 == 0 ? gray : darkGray;
                        }
                    }
                    tex.SetPixels32(x, y, w, h, colorBuffer);
                }
            }
            tex.Apply();
            return tex;
        }
        #endregion

        #region 初始化
        private void Init_SpriteGeneration()
        {
            if (Application.isEditor)
            {
                backgroundTex = GenerateSpriteBackgroundTexture(MAX_BACKGROUND_TEX_WIDTH, MAX_BACKGROUND_TEX_HEIGHT);
            }
        }
        #endregion

        private const int COLOR_BUFFER_WIDTH = 128;
        private const int COLOR_BUFFER_HEIGHT = 128;
        private const int MAX_BACKGROUND_TEX_WIDTH = 2560;
        private const int MAX_BACKGROUND_TEX_HEIGHT = 2560;

        [Header("Sprite Generate")]
        [SerializeField]
        private GeneratedResourceManifest generatedResourceManifest = null!;
        private Texture2D backgroundTex = null!;
        private Color32[] spriteColorBuffer = new Color32[COLOR_BUFFER_WIDTH * COLOR_BUFFER_HEIGHT];
    }
}
